import { MeshStandardNodeMaterial } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const mainGroup = new ctx.THREE.Group();

  // Create local backdrop to prevent black void (7x6 at z=-2.5)
  const backdropGeo = new ctx.THREE.PlaneGeometry(8, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.1
  });

  // Use TSL gradients using exact spec colors (ink: #16161d, surface: #0b0b10)
  backdropMat.colorNode = mix(
    vec3(0.043, 0.043, 0.063), // #0b0b10
    vec3(0.086, 0.086, 0.114), // #16161d
    uv().y
  );

  const backdrop = new ctx.THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  mainGroup.add(backdrop);

  // Setup local lights for rich product rendering
  const keyLight = new ctx.THREE.DirectionalLight('#e8ecf2', 1.2);
  keyLight.position.set(3, 4, 3);
  mainGroup.add(keyLight);

  const rimLight = new ctx.THREE.DirectionalLight('#ff2a38', 0.8);
  rimLight.position.set(-3, -2, 1);
  mainGroup.add(rimLight);

  // Interactive core container
  const container = new ctx.THREE.Group();
  mainGroup.add(container);

  // Card Plate (machined-metal PBR)
  const plateGeo = new ctx.THREE.BoxGeometry(3.0, 1.8, 0.08);
  const plateMat = new MeshStandardNodeMaterial({
    color: '#0b0b10',
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.2
  });
  const plate = new ctx.THREE.Mesh(plateGeo, plateMat);
  container.add(plate);

  // Accent Edge Border
  const borderGeo = new ctx.THREE.BoxGeometry(3.04, 1.84, 0.04);
  const borderMat = new MeshStandardNodeMaterial({
    color: '#16161d',
    roughness: 0.4,
    metalness: 0.1
  });
  const border = new ctx.THREE.Mesh(borderGeo, borderMat);
  border.position.z = -0.01;
  container.add(border);

  // Load Gear Mesh
  const gearUrl = config.meshUrl || '/prism-mock/orrery/meshes/gear-a.glb';
  let loadedGear = null;
  let rotationTween = null;

  ctx.glbLoader.loadGLB(gearUrl).then((gltf) => {
    loadedGear = gltf.scene;
    loadedGear.scale.setScalar(0.55);
    loadedGear.position.set(0.7, 0.0, 0.08);

    loadedGear.traverse((child) => {
      if (child.isMesh) {
        child.material = new MeshStandardNodeMaterial({
          color: '#e8ecf2',
          metalness: 0.55,
          roughness: 0.5,
          clearcoat: 0.15
        });
      }
    });

    container.add(loadedGear);

    // Continuous idle rotation representing mechanical watch movement
    rotationTween = gsap.to(loadedGear.rotation, {
      y: Math.PI * 2,
      duration: 15,
      repeat: -1,
      ease: 'none'
    });
  });

  // Extract Text Info
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const valStr = textItems[0]?.text ?? "28,800";
  const labelStr = textItems[1]?.text ?? "A/h FREQUENCY";

  // Value text (Display Lora-like bold)
  const valueText = ctx.fontAtlas.createText(valStr, {
    fontSize: 48,
    color: '#e8ecf2',
    align: 'left'
  });
  valueText.position.set(-1.2, 0.2, 0.06);
  container.add(valueText);

  // Label text (Mono-styled)
  const labelText = ctx.fontAtlas.createText(labelStr, {
    fontSize: 12,
    color: '#ff2a38',
    align: 'left',
    letterSpacingPx: 1.5
  });
  labelText.position.set(-1.2, -0.3, 0.06);
  container.add(labelText);

  // Apply "parallax-scroll" Cinematic Primitive
  const scrollPrimitive = ctx.primitives['parallax-scroll'](container, { intensity: 0.25 });

  // Interactions (GSAP hover and click)
  let hoverTl = null;
  const clickTimelines = [];

  mainGroup.userData.handlers = {
    pointerenter: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      // Rise-in subtle lift
      hoverTl.to(container.position, { z: 0.15, duration: 0.4, ease: 'power2.out' });
      // Shifting border edge to active accent color
      hoverTl.to(borderMat.color, { r: 1.0, g: 0.16, b: 0.22, duration: 0.3 }, 0);
    },
    pointerleave: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(container.position, { z: 0, duration: 0.4, ease: 'power2.out' });
      hoverTl.to(borderMat.color, { r: 0.086, g: 0.086, b: 0.114, duration: 0.3 }, 0);
    },
    click: () => {
      const clickTl = gsap.timeline()
        .to(container.scale, { x: 0.95, y: 0.95, z: 0.95, duration: 0.1, ease: 'power2.out' })
        .to(container.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'back.out(2)' });
      clickTimelines.push(clickTl);

      ctx.emit('hub-home.select', { value: valStr, label: labelStr });
    }
  };

  // Safe Cleanup
  mainGroup.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (rotationTween) rotationTween.kill();
    clickTimelines.forEach((tl) => tl.kill());

    if (scrollPrimitive && typeof scrollPrimitive.cleanup === 'function') {
      scrollPrimitive.cleanup();
    }

    // Dispose geometries & materials
    backdropGeo.dispose();
    backdropMat.dispose();
    plateGeo.dispose();
    plateMat.dispose();
    borderGeo.dispose();
    borderMat.dispose();
  };

  return mainGroup;
}
